<script>
(function () {
  "use strict";
  function init() {
    var cards = Array.prototype.slice.call(document.querySelectorAll("#tl-grid .tl-card"));
    var chips = Array.prototype.slice.call(document.querySelectorAll(".tl-chip"));
    var sizeSel = document.getElementById("tl-size");
    var priceSel = document.getElementById("tl-price");
    var countEl = document.getElementById("tl-count");
    var emptyEl = document.getElementById("tl-empty");
    var state = { cat: "All", size: "all", price: "all" };

    function priceOk(price, range) {
      if (range === "all") return true;
      var parts = range.split("-");
      var min = Number(parts[0]);
      var max = parts[1] === "" ? Infinity : Number(parts[1]);
      return price >= min && price < max;
    }

    function apply() {
      var shown = 0;
      cards.forEach(function (card) {
        var sizes = (card.getAttribute("data-sizes") || "").split(" ");
        var price = Number(card.getAttribute("data-price"));
        var ok =
          (state.cat === "All" || card.getAttribute("data-category") === state.cat) &&
          (state.size === "all" || sizes.indexOf(state.size) !== -1) &&
          priceOk(price, state.price);
        card.hidden = !ok;
        if (ok) shown++;
      });
      if (countEl) countEl.textContent = "Showing " + shown + " of " + cards.length + " products";
      if (emptyEl) emptyEl.hidden = shown !== 0;
    }

    function setCat(cat) {
      state.cat = cat;
      chips.forEach(function (chip) {
        var on = chip.getAttribute("data-cat") === cat;
        chip.classList.toggle("tl-on", on);
        chip.setAttribute("aria-pressed", on ? "true" : "false");
      });
    }

    function reset() {
      setCat("All");
      state.size = "all";
      state.price = "all";
      if (sizeSel) sizeSel.value = "all";
      if (priceSel) priceSel.value = "all";
      apply();
    }

    chips.forEach(function (chip) {
      chip.addEventListener("click", function () {
        setCat(chip.getAttribute("data-cat"));
        apply();
      });
    });
    if (sizeSel) sizeSel.addEventListener("change", function () { state.size = sizeSel.value; apply(); });
    if (priceSel) priceSel.addEventListener("change", function () { state.price = priceSel.value; apply(); });
    var resetBtn = document.getElementById("tl-reset");
    var emptyReset = document.getElementById("tl-empty-reset");
    if (resetBtn) resetBtn.addEventListener("click", reset);
    if (emptyReset) emptyReset.addEventListener("click", reset);

    // Hide nav links whose target section does not exist (yet), so no in-page link is broken.
    var links = document.querySelectorAll("#tl-navlist a");
    Array.prototype.forEach.call(links, function (a) {
      var id = (a.getAttribute("href") || "").slice(1);
      if (id && !document.getElementById(id)) {
        var li = a.parentNode;
        if (li) li.hidden = true;
      }
    });

    apply();
  }
  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", init);
  } else {
    init();
  }
})();
</script>
